			-- Ensure there are at least two words before indexing
			extra1 = (extra1[1] or "") .. " " .. (extra1[2] or "")
			extra2 = (extra2[1] or "") .. " " .. (extra2[2] or "")
			extra3 = (extra3[1] or "") .. " " .. (extra3[2] or "")

			for i, v in pairs(thingies) do
				if v.Name:lower() == text1:lower() then
					if v.Extra then
						if v.Extra:lower() == extra1:lower() then
							Berg.Text = "Bergmann:" .. v.Show
						end
					else
						Berg.Text = "Bergmann:" .. v.Show
					end
				end

				if v.Name:lower() == text2:lower() then
					if v.Extra then
						if v.Extra:lower() == extra2:lower() then
							Halfwell.Text = "Halfwell:" .. v.Show
						end
					else
						Halfwell.Text = "Halfwell:" .. v.Show
					end
				end

				if v.Name:lower() == text3:lower() then
					if v.Extra then
						if v.Extra:lower() == extra3:lower() then
							Alamont.Text = "Alamont:" .. v.Show
						end
					else
						Alamont.Text = "Alamont:" .. v.Show
					end
				end
			end
			FreeYawn.Enabled = true
		end
	elseif not enabled then
		FreeYawn.Enabled = false
	end
	wait(refreshrate)
end
